"""Patches the platform folders generated by `flutter create`.

Run from the project root after `flutter create`:
    python3 tool/patch_platforms.py

Writes the Android app gradle file + manifest (notifications, AdMob, billing,
release signing) and adds the AdMob id to the iOS Info.plist.
"""
import os
import re

APP_ID = "com.sukhadewe.waterintaker"
APP_LABEL = "Waddle"
# AdMob App IDs - TEST ids. Replace with your real AdMob app ids before release.
ADMOB_ANDROID_APP_ID = os.environ.get("ADMOB_ANDROID_APP_ID") or "ca-app-pub-3940256099942544~3347511713"
ADMOB_IOS_APP_ID = os.environ.get("ADMOB_IOS_APP_ID") or "ca-app-pub-3940256099942544~1458002511"

GRADLE = """import java.io.FileInputStream
import java.util.Properties

plugins {
    id("com.android.application")
    id("kotlin-android")
    id("dev.flutter.flutter-gradle-plugin")
}

val keystoreProperties = Properties()
val keystorePropertiesFile = rootProject.file("key.properties")
if (keystorePropertiesFile.exists()) {
    keystoreProperties.load(FileInputStream(keystorePropertiesFile))
}

android {
    namespace = "%(app_id)s"
    compileSdk = flutter.compileSdkVersion
    ndkVersion = flutter.ndkVersion

    compileOptions {
        sourceCompatibility = JavaVersion.VERSION_11
        targetCompatibility = JavaVersion.VERSION_11
        isCoreLibraryDesugaringEnabled = true
    }

    kotlinOptions {
        jvmTarget = JavaVersion.VERSION_11.toString()
    }

    defaultConfig {
        applicationId = "%(app_id)s"
        minSdk = maxOf(flutter.minSdkVersion, 24)
        targetSdk = flutter.targetSdkVersion
        versionCode = flutter.versionCode
        versionName = flutter.versionName
        multiDexEnabled = true
    }

    signingConfigs {
        create("release") {
            if (keystorePropertiesFile.exists()) {
                keyAlias = keystoreProperties["keyAlias"] as String
                keyPassword = keystoreProperties["keyPassword"] as String
                storeFile = file(keystoreProperties["storeFile"] as String)
                storePassword = keystoreProperties["storePassword"] as String
            }
        }
    }

    buildTypes {
        release {
            signingConfig = if (keystorePropertiesFile.exists())
                signingConfigs.getByName("release")
            else
                signingConfigs.getByName("debug")
        }
    }
}

flutter {
    source = "../.."
}

dependencies {
    coreLibraryDesugaring("com.android.tools:desugar_jdk_libs:2.1.4")
}
""" % {"app_id": APP_ID}

MANIFEST = """<manifest xmlns:android="http://schemas.android.com/apk/res/android">
    <uses-permission android:name="android.permission.INTERNET"/>
    <uses-permission android:name="android.permission.POST_NOTIFICATIONS"/>
    <uses-permission android:name="android.permission.RECEIVE_BOOT_COMPLETED"/>
    <uses-permission android:name="android.permission.VIBRATE"/>
    <uses-permission android:name="com.google.android.gms.permission.AD_ID"/>

    <application
        android:label="%(label)s"
        android:name="${applicationName}"
        android:icon="@mipmap/ic_launcher">
        <activity
            android:name=".MainActivity"
            android:exported="true"
            android:launchMode="singleTop"
            android:taskAffinity=""
            android:theme="@style/LaunchTheme"
            android:configChanges="orientation|keyboardHidden|keyboard|screenSize|smallestScreenSize|locale|layoutDirection|fontScale|screenLayout|density|uiMode"
            android:hardwareAccelerated="true"
            android:windowSoftInputMode="adjustResize">
            <meta-data
              android:name="io.flutter.embedding.android.NormalTheme"
              android:resource="@style/NormalTheme"
              />
            <intent-filter>
                <action android:name="android.intent.action.MAIN"/>
                <category android:name="android.intent.category.LAUNCHER"/>
            </intent-filter>
        </activity>

        <meta-data android:name="flutterEmbedding" android:value="2" />

        <meta-data
            android:name="com.google.android.gms.ads.APPLICATION_ID"
            android:value="%(admob)s"/>

        <receiver android:exported="false" android:name="com.dexterous.flutterlocalnotifications.ScheduledNotificationReceiver" />
        <receiver android:exported="false" android:name="com.dexterous.flutterlocalnotifications.ScheduledNotificationBootReceiver">
            <intent-filter>
                <action android:name="android.intent.action.BOOT_COMPLETED"/>
                <action android:name="android.intent.action.MY_PACKAGE_REPLACED"/>
                <action android:name="android.intent.action.QUICKBOOT_POWERON" />
                <action android:name="com.htc.intent.action.QUICKBOOT_POWERON"/>
            </intent-filter>
        </receiver>
    </application>
    <queries>
        <intent>
            <action android:name="android.intent.action.PROCESS_TEXT"/>
            <data android:mimeType="text/plain"/>
        </intent>
    </queries>
</manifest>
""" % {"label": APP_LABEL, "admob": ADMOB_ANDROID_APP_ID}


def patch_android():
    app = os.path.join("android", "app")
    if not os.path.isdir(app):
        print("no android folder, skipping")
        return
    groovy = os.path.join(app, "build.gradle")
    if os.path.exists(groovy):
        os.remove(groovy)
    with open(os.path.join(app, "build.gradle.kts"), "w") as f:
        f.write(GRADLE)
    with open(os.path.join(app, "src", "main", "AndroidManifest.xml"), "w") as f:
        f.write(MANIFEST)
    print("android patched")


def patch_ios():
    plist = os.path.join("ios", "Runner", "Info.plist")
    if not os.path.exists(plist):
        print("no ios folder, skipping")
        return
    s = open(plist).read()
    if "GADApplicationIdentifier" not in s:
        extra = (
            "\t<key>GADApplicationIdentifier</key>\n\t<string>%s</string>\n"
            "\t<key>SKAdNetworkItems</key>\n\t<array>\n\t\t<dict>\n\t\t\t<key>SKAdNetworkIdentifier</key>\n"
            "\t\t\t<string>cstr6suwn9.skadnetwork</string>\n\t\t</dict>\n\t</array>\n"
            "\t<key>NSUserTrackingUsageDescription</key>\n"
            "\t<string>This identifier will be used to deliver more relevant ads to you.</string>\n"
        ) % ADMOB_IOS_APP_ID
        s = re.sub(r"</dict>\s*</plist>\s*$", extra + "</dict>\n</plist>\n", s)
    s = re.sub(r"(<key>CFBundleDisplayName</key>\s*<string>)[^<]*(</string>)", r"\g<1>%s\g<2>" % APP_LABEL, s)
    open(plist, "w").write(s)
    print("ios patched")


if __name__ == "__main__":
    patch_android()
    patch_ios()
